'use client'

import { useEffect } from 'react'

export default function Error({
  error,
  reset
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error('Page error:', error)
  }, [error])

  return (
    <div className="rounded-lg border border-red-200 bg-red-50 p-6">
      <h2 className="text-lg font-semibold text-red-800">Something went wrong</h2>
      <p className="mt-2 text-red-600">We could not load this page. Please try again.</p>
      <button
        onClick={reset}
        className="mt-4 rounded bg-red-700 px-4 py-2 text-white"
      >
        Try again
      </button>
    </div>
  )
}

import { notFound } from 'next/navigation'

async function Post({ params }: { params: { slug: string } }) {
  const post = await fetchPost(params.slug)

  if (!post) {
    notFound()
  }

  return (
    <article>
      <h1>{post.title}</h1>
      <div dangerouslySetInnerHTML={{ __html: post.content }} />
    </article>
  )
}

async function ProductPage({ id }: { id: string }) {
  const product = await fetchProduct(id)

  let recommendations
  try {
    recommendations = await fetchRecommendations(id)
  } catch {
    recommendations = [] // graceful fallback
  }

  return (
    <div>
      <h1>{product.name}</h1>
      <p>{product.description}</p>

      {recommendations.length > 0 ? (
        <Recommendations items={recommendations} />
      ) : (
        <p className="text-gray-500">No recommendations available right now.</p>
      )}
    </div>
  )
}
